# Hand-written R5900 versions of the sound_tests.c kernels (bench variants
# asm and asm-vu0), generated by asm/gen/app_files.py from asm/gen/sound.py.
# n32 ABI. The kernels use the data of sound_tests.c (KERNEL_DATA) and end
# with app_hash of their output. Only energy has a VU0 version (asm-vu0).
# Optimized: yes, all. Measured on the PS2 (asm/harness/app.c), feature
# clang in parentheses:
#   Mix 8 Voices   108.3 Msmp/s (83.4)  MMI pmulth per voice and side
#   ADPCM Decode    25.1 Msmp/s (21.6)  the sample-to-sample chain shortened
#   FIR 32          20.4 Msmp/s (10.5)  pmaddh on qfsrv-shifted inputs
#   Resample        27.6 Msmp/s (27.3)  scalar, 8 per iteration (4: 26.1)
#   Correlate Q15    539 MMAC/s (264)   pmaddh, qfsrv once per lag % 8
#   Energy f32  VU0 117.8, FPU 112.6 Msmp/s (96.6, 95.9): memory-bound; PREF
#                3 lines ahead (VU0) and 1 line (FPU; 2: 96.5, 3: 88.8)

	.set	noreorder
	.set	noat

# gfx_mem: the offsets of its buffers
#define SPRITE		0x0000
#define FRAME		0x4400
#define INDEXED		0x8800
#define PALETTE		0x9c00
#define FRAME16		0xa000
#define SCALED		0xc400
# geom_mem
#define VERTS		0x0000
#define NORMALS		0x2400
#define SCALED_V	0x4800
#define FACE_NORMALS	0x6c00
#define SCREEN		0x9400
#define XFORMED		0xb800
#define COLORS		0xdc00
#define FACE_NORMALS_V	0xec00
#define VISIBLE		0x10c00

# reg = symbol + offset (any 32-bit offset), using $1
#define ADDR(reg, sym, off) \
	lui	$1, %hi(sym); addiu reg, $1, %lo(sym); \
	lui	$1, ((off) >> 16); ori $1, $1, ((off) & 0xffff); addu reg, reg, $1

